import networkx as nx
import json
import os
import pandas as pd
from typing import Dict, List


def search_algorithm(src, dsts, G, num_partitions):
    """Directed Steiner broadcast via metric closure + minimum spanning
    arborescence (Edmonds), competing against an undirected library
    Steiner tree and a shortest-path tree. The cheapest pruned edge set
    serves all partitions, so shared trunk edges are paid once per
    partition instead of once per destination."""
    h = G.copy()
    h.remove_edges_from(list(h.in_edges(src)) + list(nx.selfloop_edges(h)))

    bc_topology = BroadCastTopology(src, dsts, num_partitions)
    terminals = set(d for d in dsts if d != src)

    def tree_cost(edges):
        return sum(G[s][t].get("cost") or 0 for s, t in edges)

    def prune(edges):
        """Drop branches ending at non-destination leaves."""
        edges = set(edges)
        changed = True
        while changed:
            changed = False
            out_deg, in_deg = {}, {}
            for s, t in edges:
                out_deg[s] = out_deg.get(s, 0) + 1
                in_deg[t] = in_deg.get(t, 0) + 1
            for s in list(out_deg):
                if s != src and s not in terminals and s not in in_deg:
                    edges = {e for e in edges if e[0] != s}
                    changed = True
        return edges

    def repair(edges):
        """Ensure every terminal is reachable; else attach via Dijkstra."""
        edges = set(edges)
        for d in sorted(terminals):
            reach = {src}
            frontier = [src]
            adj = {}
            for s, t in edges:
                adj.setdefault(s, []).append(t)
            while frontier:
                u = frontier.pop()
                for v in adj.get(u, ()):
                    if v not in reach:
                        reach.add(v)
                        frontier.append(v)
            if d not in reach:
                try:
                    _, path = nx.multi_source_dijkstra(h, reach, d, weight="cost")
                except Exception:
                    try:
                        path = nx.dijkstra_path(h, src, d, weight="cost")
                    except Exception:
                        path = nx.dijkstra_path(G, src, d, weight="cost")
                for i in range(len(path) - 1):
                    edges.add((path[i], path[i + 1]))
        return edges

    # --- Candidate A: metric closure + min arborescence (Edmonds) ---
    T = [src] + sorted(terminals)
    sp = {}
    for u in T:
        try:
            sp[u] = nx.single_source_dijkstra(h, u, weight="cost")
        except Exception:
            sp[u] = ({}, {})
    closure = nx.DiGraph()
    for u in T:
        d, p = sp[u]
        for v in T:
            if v != u and v in d:
                closure.add_edge(u, v, weight=d[v])
    arbo_edges = set()
    try:
        arb = nx.minimum_spanning_arborescence(closure, source=src)
        for u, v in arb.edges():
            path = sp[u][1][v]
            for i in range(len(path) - 1):
                arbo_edges.add((path[i], path[i + 1]))
    except Exception:
        pass

    # --- Candidate B: undirected library Steiner, mapped to directed arcs ---
    steiner_edges = set()
    try:
        from networkx.algorithms.approximation import steiner_tree
        und = nx.Graph()
        for s, t, d in h.edges(data=True):
            c = d.get("cost")
            if c is None:
                continue
            if und.has_edge(s, t) and und[s][t]["cost"] <= c:
                continue
            und.add_edge(s, t, cost=c)
        st = steiner_tree(und, set(terminals) | {src}, weight="cost")
        for u, v in st.edges():
            if h.has_edge(u, v):
                steiner_edges.add((u, v))
            elif h.has_edge(v, u):
                steiner_edges.add((v, u))
    except Exception:
        pass

    # --- Candidate C: shortest-path tree from src ---
    spt_edges = set()
    try:
        _, paths = nx.multi_source_dijkstra(h, {src}, weight="cost")
        for d in terminals:
            if d in paths:
                p = paths[d]
                for i in range(len(p) - 1):
                    spt_edges.add((p[i], p[i + 1]))
    except Exception:
        pass

    # --- Candidate D: union of per-dst shortest paths (safe fallback) ---
    fallback_edges = set()
    for d in terminals:
        try:
            path = nx.dijkstra_path(h, src, d, weight="cost")
        except Exception:
            path = nx.dijkstra_path(G, src, d, weight="cost")
        for i in range(len(path) - 1):
            fallback_edges.add((path[i], path[i + 1]))

    candidates = [prune(repair(c)) for c in
                  (arbo_edges, steiner_edges, spt_edges, fallback_edges) if c]
    tree_edges = min(candidates, key=tree_cost)

    # --- Emit per-partition paths along the shared tree ---
    tree = h.copy()
    tree.remove_edges_from(
        [e for e in list(tree.edges) if e not in tree_edges])
    tree.add_edges_from(
        [(s, t, dict(G[s][t])) for (s, t) in tree_edges if not tree.has_edge(s, t)])

    for dst in dsts:
        if dst == src:
            continue
        if dst in tree and nx.has_path(tree, src, dst):
            path = nx.dijkstra_path(tree, src, dst, weight="cost")
            edges = [[path[i], path[i + 1], G[path[i]][path[i + 1]]]
                     for i in range(len(path) - 1)]
        else:
            try:
                path = nx.dijkstra_path(h, src, dst, weight="cost")
            except Exception:
                path = nx.dijkstra_path(G, src, dst, weight="cost")
            edges = [[path[i], path[i + 1], G[path[i]][path[i + 1]]]
                     for i in range(len(path) - 1)]
        for j in range(num_partitions):
            for e in edges:
                bc_topology.append_dst_partition_path(dst, j, e)

    return bc_topology


class SingleDstPath(Dict):
    partition: int
    edges: List[List]  # [[src, dst, edge data]]


class BroadCastTopology:
    def __init__(self, src: str, dsts: List[str], num_partitions: int = 4, paths: Dict[str, SingleDstPath] = None):
        self.src = src  # single str
        self.dsts = dsts  # list of strs
        self.num_partitions = num_partitions

        # dict(dst) --> dict(partition) --> list(nx.edges)
        # example: {dst1: {partition1: [src->node1, node1->dst1], partition 2: [src->dst1]}}
        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {dst: {str(i): None for i in range(num_partitions)} for dst in dsts}

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        """
        Set paths for partition = partition to reach dst
        """
        partition = str(partition)
        self.paths[dst][partition] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        """
        Append path for partition = partition to reach dst
        """
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)

def make_nx_graph(cost_path=None, throughput_path=None, num_vms=1):
    """
    Default graph with capacity constraints and cost info
    nodes: regions, edges: links
    per edge:
        throughput: max tput achievable (gbps)
        cost: $/GB
        flow: actual flow (gbps), must be < throughput, default = 0
    """
    # Use relative path from this file's location
    current_dir = os.path.dirname(os.path.abspath(__file__))

    if cost_path is None:
        cost = pd.read_csv(os.path.join(current_dir, "profiles/cost.csv"))
    else:
        cost = pd.read_csv(cost_path)

    if throughput_path is None:
        throughput = pd.read_csv(os.path.join(current_dir, "profiles/throughput.csv"))
    else:
        throughput = pd.read_csv(throughput_path)

    G = nx.DiGraph()
    for _, row in throughput.iterrows():
        if row["src_region"] == row["dst_region"]:
            continue
        G.add_edge(row["src_region"], row["dst_region"], cost=None, throughput=num_vms * row["throughput_sent"] / 1e9)

    for _, row in cost.iterrows():
        if row["src"] in G and row["dest"] in G[row["src"]]:
            G[row["src"]][row["dest"]]["cost"] = row["cost"]

    # some pairs not in the cost grid
    no_cost_pairs = []
    for edge in G.edges.data():
        src, dst = edge[0], edge[1]
        if edge[-1]["cost"] is None:
            no_cost_pairs.append((src, dst))
    print("Unable to get costs for: ", no_cost_pairs)

    return G


# EVOLVE-BLOCK-END

# Helper functions that won't be evolved
def create_broadcast_topology(src: str, dsts: List[str], num_partitions: int = 4):
    """Create a broadcast topology instance"""
    return BroadCastTopology(src, dsts, num_partitions)

def run_search_algorithm(src: str, dsts: List[str], G, num_partitions: int):
    """Run the search algorithm and return the topology"""
    return search_algorithm(src, dsts, G, num_partitions)

